import unreal, json
world = unreal.get_editor_subsystem(unreal.UnrealEditorSubsystem).get_editor_world()
results=[]
for x,y in [(1100,800),(1100,1050),(1900,800),(2400,925),(1100,1400),(0,800)]:
    hit = unreal.SystemLibrary.line_trace_single(world, unreal.Vector(x,y,2000), unreal.Vector(x,y,-1000), unreal.TraceTypeQuery.ECC_VISIBILITY, True, [], unreal.DrawDebugTrace.NONE, True)
    b = hit.to_tuple()
    if b[0]:
        results.append({'xy':[x,y], 'z':b[4].z, 'actor':b[9].get_actor_label() if b[9] else None})
    else: results.append({'xy':[x,y], 'no_hit':True})
print(json.dumps(results))
